<?php require __DIR__.'/../includes/auth.php';require __DIR__.'/../config/database.php';$rows=$pdo->query("SELECT * FROM enquiries ORDER BY created_at DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-100 p-8"><main class="mx-auto max-w-7xl"><h1 class="text-3xl font-black">Enquiries</h1><div class="mt-6 overflow-x-auto rounded-2xl bg-white"><table class="w-full text-left"><tr class="border-b"><th class="p-4">Name</th><th>Email</th><th>Company</th><th>Message</th><th>Status</th></tr><?php foreach($rows as $r):?><tr class="border-b"><td class="p-4"><?=$r['name']?></td><td><?=$r['email']?></td><td><?=$r['company']?></td><td><?=htmlspecialchars($r['message'])?></td><td><?=$r['status']?></td></tr><?php endforeach;?></table></div></main></body></html>